        Object.fromEntries(
          Object.entries(prev).map(([pumpId, pump]) => [
            pumpId,
            pump.on ? { ...pump, runtime: pump.runtime + 1 } : pump,
          ])
        )
      );
    }, 60000);

    return () => clearInterval(interval);
  }, []);

  const togglePump = (pumpId) => {
