      }

      let responseText = aiResponses[responseKey];
      if (responseKey === "default") {
        responseText = responseText
          .replace("{moisture}", sensorData.soilMoisture)
          .replace("{temp}", sensorData.temperature)
          .replace("{hum}", sensorData.humidity);
